from typing import Optional, Any, Dict, List, Callable

class ValidationError(Exception):
    """自定义验证异常类"""
    def __init__(self, message: str, field: Optional[str] = None):
        self.message = message
        self.field = field
        super().__init__(self.message)


def process_data(data: dict) -> dict:
    result = {}
    for key, value in data.items():
        result[key] = str(value).upper()
    return result


class DataHandler:
    # 验证规则配置化 - 默认验证规则
    DEFAULT_VALIDATION_RULES: Dict[str, Dict[str, Any]] = {
        'min_length': {'value': 1, 'enabled': True},
        'max_length': {'value': 1000, 'enabled': False},
        'allow_empty': {'value': False, 'enabled': True},
    }

    def __init__(self, source: str, validation_rules: Optional[Dict[str, Dict[str, Any]]] = None):
        self.source = source
        self.data = {}
        # 使用自定义验证规则或默认规则
        self.validation_rules = validation_rules or self.DEFAULT_VALIDATION_RULES.copy()

    def load(self) -> bool:
        return True

    def transform(self, func) -> dict:
        return {k: func(v) for k, v in self.data.items()}

    def save(self, path: str) -> bool:
        return True

    @classmethod
    def validate_input(cls, value: str, custom_rules: Optional[Dict[str, Dict[str, Any]]] = None) -> bool:
        """
        验证输入值是否合法

        Args:
            value: 待验证的值
            custom_rules: 自定义验证规则（可选）

        Returns:
            bool: 验证是否通过

        Raises:
            ValidationError: 当验证失败时抛出
        """
        rules = custom_rules or cls.DEFAULT_VALIDATION_RULES

        # 检查是否启用长度验证
        if rules.get('min_length', {}).get('enabled', False):
            min_len = rules['min_length']['value']
            if len(value) < min_len:
                raise ValidationError(
                    f"Value length must be at least {min_len}",
                    field="input_value"
                )

        # 检查是否启用最大长度验证
        if rules.get('max_length', {}).get('enabled', False):
            max_len = rules['max_length']['value']
            if len(value) > max_len:
                raise ValidationError(
                    f"Value length must not exceed {max_len}",
                    field="input_value"
                )

        # 检查是否允许空值
        if rules.get('allow_empty', {}).get('enabled', False):
            allow_empty = rules['allow_empty']['value']
            if not allow_empty and len(value) == 0:
                raise ValidationError(
                    "Empty value is not allowed",
                    field="input_value"
                )

        return True

    @classmethod
    def validate_with_rules(cls, value: str, validators: List[Callable[[str], bool]]) -> bool:
        """
        使用自定义验证器列表进行验证

        Args:
            value: 待验证的值
            validators: 验证器函数列表

        Returns:
            bool: 验证是否通过

        Raises:
            ValidationError: 当验证失败时抛出
        """
        for validator in validators:
            if not validator(value):
                raise ValidationError(
                    f"Validation failed for validator: {validator.__name__}",
                    field="input_value"
                )
        return True
